const rows = $input.all();
const expected = ['positive', 'negative', 'neutral'];
if (rows.length !== 3) throw new Error('Expected three outputs.');
return rows.map((row, i) => {
 const actual = String(row.json.text ?? '').trim().toLowerCase().replace(/[.!]$/g, '');
 if (actual !== expected[i]) throw new Error(`Item ${i + 1}: expected ${expected[i]}, received ${actual}`);
 return { json: { passed: true, sentiment: actual }, pairedItem: { item: i } };
});
